using namespace std;

void solve(istream& in, ostream& out) {
    const vector<string> animals = {"Ox", "Tiger", "Rabbit", "Dragon",
        "Snake", "Horse", "Goat", "Monkey", "Rooster", "Dog", "Pig", "Rat"};
    map<string, int> offset;
    offset["Bessie"] = 0;
    int n;
    in >> n;
    for (int i = 0; i < n; ++i) {
        string name, born, wordIn, direction, animal, year, from, reference;
        in >> name >> born >> wordIn >> direction >> animal >> year >> from >> reference;
        int target = static_cast<int>(find(animals.begin(), animals.end(), animal) - animals.begin());
        int base = offset.at(reference);
        int baseRank = (base % 12 + 12) % 12;
        int distance = direction == "next" ? (target - baseRank + 12) % 12
                                           : (baseRank - target + 12) % 12;
        if (distance == 0) distance = 12;
        offset[name] = base + (direction == "next" ? distance : -distance);
    }
    out << abs(offset.at("Elsie")) << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
