#include <iostream>
#include <set>
#include <utility>
#include <vector>
using namespace std;

void solve(istream& in, ostream& out) {
    using Cell = pair<int, int>;
    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};
    set<Cell> occupied;
    auto degree = [&](Cell p) {
        int result = 0;
        for (int d = 0; d < 4; ++d)
            result += occupied.count({p.first + dx[d], p.second + dy[d]});
        return result;
    };
    int n, comfortable = 0;
    in >> n;
    for (int i = 0; i < n; ++i) {
        Cell p;
        in >> p.first >> p.second;
        vector<Cell> affected = {p};
        for (int d = 0; d < 4; ++d) {
            Cell q = {p.first + dx[d], p.second + dy[d]};
            if (occupied.count(q)) {
                comfortable -= degree(q) == 3;
                affected.push_back(q);
            }
        }
        occupied.insert(p);
        for (Cell q : affected) comfortable += degree(q) == 3;
        out << comfortable << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
