#include <iostream>
#include <string>
using namespace std;

void solve(istream& in, ostream& out) {
    int paths;
    in >> paths;
    while (paths--) {
        string path;
        in >> path;
        long long x = 0, y = 0, signedTwiceArea = 0;
        for (char direction : path) {
            long long nextX = x, nextY = y;
            if (direction == 'N') ++nextY;
            if (direction == 'E') ++nextX;
            if (direction == 'S') --nextY;
            if (direction == 'W') --nextX;
            signedTwiceArea += x * nextY - nextX * y;
            x = nextX;
            y = nextY;
        }
        out << (signedTwiceArea < 0 ? "CW" : "CCW") << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
